def _parse_attrs(options: Dict[str, Any]) ->Dict[str, Any]:
    attrs = {}
    if 'alt' in options:
        attrs['alt'] = options['alt']

    width = options.get('width', '')
    if width:
        m = _num_re.match(width)
        if m:
            num = m.group(0)
            rest = width[len(num):]
            if not rest or rest == 'px':
                attrs['width'] = num + 'px'
            else:
                attrs['width'] = width
        else:
            attrs['width'] = width

    height = options.get('height', '')
    if height:
        m = _num_re.match(height)
        if m:
            num = m.group(0)
            rest = height[len(num):]
            if not rest or rest == 'px':
                attrs['height'] = num + 'px'
            else:
                attrs['height'] = height
        else:
            attrs['height'] = height

    align = options.get('align', '')
    if align and align in _allowed_aligns:
        attrs['align'] = align

    target = options.get('target', '')
    if target:
        attrs['target'] = target

    return attrs

def render_block_image(self: 'HTMLRenderer', src: str, alt: Optional[str]=
    None, width: Optional[str]=None, height: Optional[str]=None, **attrs: Any
    ) ->str:
    target = attrs.get('target', '')
    align = attrs.get('align', '')

    _alt = escape_text(alt) if alt else ''
    _src = escape_url(src)

    html = '<img src="' + _src + '" alt="' + _alt + '"'
    if width:
        html += ' width="' + width + '"'
    if height:
        html += ' height="' + height + '"'
    if align:
        html += ' class="align-' + align + '"'
    html += ' />'

    if target:
        _target = escape_url(target)
        html = '<a href="' + _target + '">' + html + '</a>'

    return html + '\n'

def parse(self, block: 'BlockParser', m: Match[str], state: 'BlockState'
    ) ->Dict[str, Any]:
    options = dict(self.parse_options(m))
    attrs = _parse_attrs(options)
    attrs['src'] = self.parse_title(m)
    return {'type': 'block_image', 'attrs': attrs}

def __call__(self, directive: 'BaseDirective', md: 'Markdown') ->None:
    directive.register(self.NAME, self.parse)
    assert md.renderer is not None
    if md.renderer.NAME == 'html':
        md.renderer.register('block_image', render_block_image)
